import * as React from "react";
import { Progress as ProgressPrimitive } from "radix-ui";

import { cn } from "@/lib/didact/cn";

export interface ProgressProps
  extends React.ComponentProps<typeof ProgressPrimitive.Root> {
  /** Classes applied to the moving indicator rather than the track. */
  indicatorClassName?: string;
}

/**
 * Progress -- a neutral determinate/indeterminate progress primitive. Radix owns progressbar ARIA;
 * the indicator is a purely visual reinforcement and callers must provide an accessible name.
 */
function Progress({ className, indicatorClassName, value, max = 100, ...props }: ProgressProps) {
  const safeMax = Number.isFinite(max) && max > 0 ? max : 100;
  const safeValue = value == null ? null : Math.max(0, Math.min(safeMax, value));
  const percent = safeValue == null ? 0 : (safeValue / safeMax) * 100;

  return (
    <ProgressPrimitive.Root
      data-slot="progress"
      value={safeValue}
      max={safeMax}
      className={cn("relative h-2 w-full overflow-hidden rounded-full bg-secondary", className)}
      {...props}
    >
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        data-indeterminate={safeValue == null ? "true" : undefined}
        className={cn(
          "h-full w-full flex-1 bg-primary transition-transform duration-300 motion-reduce:transition-none data-[indeterminate=true]:opacity-40",
          indicatorClassName,
        )}
        style={{ transform: `translateX(-${100 - percent}%)` }}
      />
    </ProgressPrimitive.Root>
  );
}

export { Progress };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}
